import { Resend } from "resend";

let client: Resend | undefined;

function getClient(): Resend {
  const key = process.env.RESEND_API_KEY;
  if (!key) throw new Error("RESEND_API_KEY is not set");
  return (client ??= new Resend(key));
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

type Message = { to: string; subject: string; html: string; text: string };

// Resend resolves to { error } instead of throwing on refused messages. Email is
// best-effort: log failures so they never break the request that triggered them.
async function send({ to, subject, html, text }: Message): Promise<boolean> {
  try {
    const from = process.env.RESEND_FROM_EMAIL;
    if (!from) throw new Error("RESEND_FROM_EMAIL is not set");
    const { error } = await getClient().emails.send({ from, to, subject, html, text });
    if (error) throw new Error(`${error.name}: ${error.message}`);
    return true;
  } catch (err) {
    console.error(`[email] failed to send "${subject}":`, err);
    return false;
  }
}

export function appUrl(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  const url = appUrl();
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    text: `Hi ${user.name},\n\nWelcome to Notely! Start taking notes with your team: ${url}/dashboard\n`,
    html: `<p>Hi ${name},</p><p>Welcome to Notely! <a href="${url}/dashboard">Open your dashboard</a> to start taking notes with your team.</p>`,
  });
}

export function sendPasswordResetEmail(user: { email: string; name: string }, resetUrl: string) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\n\nThis link expires in 1 hour. If you didn't request it, ignore this email.\n`,
    html: `<p>Hi ${name},</p><p><a href="${escapeHtml(resetUrl)}">Reset your password</a>. This link expires in 1 hour.</p><p>If you didn't request this, you can ignore this email.</p>`,
  });
}
EOF
